BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY; SET LOCAL search_path=pg_catalog,public;
SELECT jsonb_build_object('captured_at',clock_timestamp(),
'columns',(SELECT jsonb_agg(jsonb_build_object('schema',table_schema,'table',table_name,'name',column_name,'type',udt_name,'nullable',is_nullable,'default',column_default) ORDER BY table_schema,table_name,ordinal_position) FROM information_schema.columns WHERE (table_schema='public' AND table_name IN('subscriptions','subscription_consumptions','subscription_alert_events','membership_plans','membership_plans_sucursal','cortesias','citas','citas_detalles','citas_grupos','citas_admin_beneficios_resumen')) OR (table_schema='app_private' AND table_name='reserva_idempotencia')),
'constraints',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',k.conname,'definition',pg_get_constraintdef(k.oid)) ORDER BY n.nspname,c.relname,k.conname) FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE (n.nspname='public' AND c.relname IN('subscriptions','subscription_consumptions','citas','citas_detalles','citas_admin_beneficios_resumen')) OR(n.nspname='app_private' AND c.relname='reserva_idempotencia')),
'indexes',(SELECT jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',indexname,'definition',indexdef) ORDER BY schemaname,tablename,indexname) FROM pg_indexes WHERE (schemaname='public' AND tablename IN('subscriptions','subscription_consumptions','citas_detalles','citas_admin_beneficios_resumen')) OR(schemaname='app_private' AND tablename='reserva_idempotencia')),
'triggers',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid)) ORDER BY c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relnamespace='public'::regnamespace AND c.relname IN('subscriptions','subscription_consumptions') AND NOT t.tgisinternal),
'tables',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl,'rls',c.relrowsecurity) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND ((n.nspname='public' AND c.relname IN('subscriptions','subscription_consumptions','citas_admin_beneficios_resumen')) OR(n.nspname='app_private' AND c.relname='reserva_idempotencia'))),
'consumptions',(SELECT jsonb_build_object('rows',count(*),'units',coalesce(sum(cantidad::bigint),0),'digest',md5(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY id_consumo),''))) FROM subscription_consumptions t),
'evidence_reservation',(SELECT jsonb_build_object('rows',count(*),'version1',count(*)FILTER(WHERE response_payload->'membership_consumption'->>'version'='1')) FROM app_private.reserva_idempotencia),
'evidence_admin',(SELECT jsonb_build_object('rows',count(*),'version1',count(*)FILTER(WHERE resumen_beneficios->'membership_consumption'->>'version'='1')) FROM citas_admin_beneficios_resumen)
) snapshot; COMMIT;
